# -*- coding: utf-8 -*-
"""Канон газовых писем КЦ (владелец 11.11) — общий для образцов и боевой генерации (gen_gaz_kc.py).
Тексты канона, задание модели, проверки фразы, отсев кодом. Ничего не выполняет при импорте."""
import random, re
ТЕХ = re.compile(r"(?i)техн\w* директор|главн\w* (инженер|технолог|энергетик|механик)|производств|технолог|энергетик|механик|начальник цеха")
РУК = re.compile(r"(?i)директор|руковод|управляющ")
def ранг(д):
    if ТЕХ.search(д): return 0
    if РУК.search(д) and not re.search(r"(?i)закуп|снабж|продаж|коммерч|маркет|финанс|бухгалт", д): return 1
    if re.search(r"(?i)закуп|снабж", д): return 2
    return 3
ИМЕНА = set("""александр алексей анатолий андрей антон аркадий артём артем борис вадим валентин валерий василий виктор виталий владимир владислав вячеслав геннадий георгий глеб григорий даниил денис дмитрий евгений егор иван игорь илья кирилл константин леонид максим марат михаил никита николай олег павел пётр петр роман руслан рустам сергей станислав степан тимур фёдор федор эдуард юрий ярослав
александра алина алла анастасия анна антонина валентина валерия вера виктория галина дарья евгения екатерина елена жанна зинаида зоя инна ирина карина кристина лариса лидия любовь людмила маргарита марина мария надежда наталья наталия нина оксана ольга полина раиса светлана софья тамара татьяна ульяна юлия яна""".split())
def обращение(fio):
    ч = [x for x in re.split(r"\s+", (fio or "").strip()) if x]
    if any(len(x.strip(".")) <= 2 or "." in x for x in ч): return None
    for i, x in enumerate(ч):
        if re.search(r"(вич|вна|ична|ьич)$", x, re.I) and i > 0 and ч[i - 1].lower() in ИМЕНА: return ч[i - 1] + " " + x
    for x in ч:
        if x.lower() in ИМЕНА: return x
    return None
# ---- кандидаты: на отрасль до 6 по имени (лучшая роль) + до 4 без имени; модель отсеет несоответствие
ПЛОХ_АДР = re.compile(r"(?i)@(site|example|test)\.(ru|com)$|\.(ua|by|kz|uz|am|ge|az|md)$")
def адрес_годен(em):
    em = (em or "").strip().lower()
    return bool(re.match(r"^[\w.+-]+@[\w.-]+\.(ru|рф|su|com|org|net|pro|biz|info)$", em)) and not ПЛОХ_АДР.search(em)
КОНК_РЕ = re.compile(r"(?i)адсорбцион|получени\w* (газ|азот|кислород)|генератор\w* (азот|кислород|газ)|(азотн|кислородн|газоразделит)\w* (станц|установ|оборуд)|воздухоразделит|мембранн\w* (установ|блок)|(производ|выпуск)\w* компрессор|компрессорн\w* (станц|оборуд|установ)|винтов\w* компрессор|осушител\w* (воздух|газ)")
ЗАДАНИЕ = """Пишем холодное письмо поставщика азотных и кислородных станций (адсорбционные PSA, получают газ на месте из сжатого воздуха). Для КАЖДОЙ компании сначала реши ok: true, только если по её ПРОДУКЦИИ видно, что это действительно производство из указанной отрасли и ему реально нужен {gaz} в техпроцессе; если продукция не из этой отрасли (торговля, логистика, услуги, станки, книги, стройматериалы и т.п.) или газ им не нужен — ok: false и фразу не пиши. Затем для ok: true дай ОДНУ фразу на русском:
f — законченное предложение (с подлежащим и сказуемым) о том, где именно в ИХ производстве нужен {gaz} (опираясь на их продукцию и техпроцесс отрасли), 10-22 слова, спокойно и по делу, без оценок и без описания проблем, конкретно про ИХ СОБСТВЕННЫЙ продукт/операцию (называй их продукцию с сайта, а не типовую продукцию отрасли: у медоварни медовуха и сидр, не вина), без цифр, без «мы/наш», без названия компании, без длинного тире, начинай не со слов «На производстве».
КОНКУРЕНТ: если компания сама производит, продаёт или обслуживает азотные/кислородные станции, генераторы газов, компрессоры, осушители, газовое оборудование — ok: false, pochemu начни со слова «конкурент». Торговля техническими газами (баллоны, жидкий газ) конкурентом НЕ считается: такая компания может сама купить станцию.
ВАЖНО для отраслей «Лазерная резка, металлообработка…» и «Электроника, приборостроение…»: ok: false там допустим ТОЛЬКО по трём причинам — конкурент, торговля/дилер без производства, сервис/услуги. Любой завод, выпускающий металлоизделия, оборудование, металлоконструкции, приборы, щиты, кабель, — ok: true, а фразу f пиши про лазерную резку металла (или пайку плат) при выпуске ИХ изделий. Выпуск станков, оборудования, металлоконструкций, приборов, кабеля — это и есть их производство (режут металл лазером на азоте, паяют платы в азоте): по этой причине НЕ отсеивай; отсеивай там только торговлю, дилеров, сервис и услуги.
{firmy}
Физика (нельзя нарушать): кислород PSA около 93 процентов не годится для резки металла кислородом и для заправки баллонов, в кислородных фразах эти применения не упоминай. Для пива и напитков азот, контактирующий с продуктом, нужен высокой чистоты, не пиши, что подойдёт любой азот. Для лазерной резки не обещай, что хватит обычной станции.
Не выдумывай применения: ok: true, только если газ ТИПИЧНО применяется в производстве именно такой продукции (MAP-фасовка орехов, сухофруктов, колбас, сыра; инертизация реакторов ЛКМ; пропеллент аэрозолей; озонирование воды и т.п.). Отсутствие слова «азот» на сайте — НЕ повод отсеивать, если продукция типично фасуется или делается с газом. Отсеивай (false): операторов вендинга и кофеен, торговые дома и дистрибьюторов без своего производства, логистику, услуги; россыпную добычу золота без фабрики и цианирования. Не приписывай компании операций, которых у неё нет по продукции (например, аэрозоли производителю моющих средств без спреев). Поле pochemu заполняй ВСЕГДА.
Не пиши про вакуумную упаковку в связке с азотом (при вакууме газ не используют).
Ответ СТРОГО JSON: {{"o": [{{"n": НОМЕР, "konk": true/false (сама делает/продаёт/обслуживает газовые станции, генераторы газов, компрессоры, осушители), "ok": true/false, "pochemu": "кратко", "f": "..."}}]}}"""
ПОВОД = ["Сейчас на крупных предприятиях формируют планы модернизации и бюджеты на следующий год, поэтому и пишу.",
         "Пишу сейчас, потому что в ноябре–декабре предприятия обычно закладывают модернизацию и бюджеты на следующий год.",
         "Многие производства как раз сейчас верстают бюджеты на следующий год, поэтому решил написать заранее.",
         "Конец года - время, когда планируют модернизацию на следующий год, поэтому пишу сейчас."]
ОХВАТ = {"N2": ["Под такие задачи проектируем и поставляем азотные станции под ключ, в том числе модульные, сразу с компрессором и осушкой воздуха.",
                "Для этого как раз ведём проекты по азоту: от одной станции под участок до модульной азотной станции в комплекте с компрессором и подготовкой воздуха.",
                "Как раз под такие процессы поставляем азотные станции под ключ, в том числе модульные: станция идёт в комплекте с компрессором и осушкой."],
         "O2": ["Под такие задачи проектируем и поставляем кислородные станции под ключ, в том числе модульные, сразу с компрессором и осушкой воздуха.",
                "Для этого как раз ведём проекты по кислороду: от одной станции под участок до модульной кислородной станции в комплекте с компрессором и подготовкой воздуха.",
                "Как раз под такие процессы поставляем кислородные станции под ключ, в том числе модульные: станция идёт в комплекте с компрессором и осушкой."]}
# владелец 11.11: «чуть больше про компрессоры, что отдельно их поставляем и станции тоже с ними»
# владелец 11.11: «слишком слабо про винтовые… проектирование компрессорной, модульные станции» — канон КЦ:
# винтовые, проект компрессорной, модульные компрессорные станции собственного производства, бренд Enger + 20 производителей
КОМПР_ОТД = ["Компрессоры - наше основное направление. Подберём винтовой компрессор, спроектируем компрессорную или поставим готовую модульную станцию.",
             "Сжатый воздух - наш основной профиль. Можем заменить один компрессор, а можем спроектировать всю компрессорную под ключ.",
             "Основное наше направление - компрессоры, есть и свой бренд Enger. Компрессорные проектируем под ключ, в том числе модульные."]
КОМПР_ОТД_КРУПН = ["Компрессоры - наше основное направление, от винтовых до центробежных. Компрессорные проектируем под ключ, в том числе модульные.",
                   "Сжатый воздух - наш основной профиль. Подберём винтовой или центробежный компрессор, спроектируем компрессорную или поставим модульную станцию."]
def компр(отр, р=None):
    """Владелец 11.11: центробежные — золото (ЗИФ) и большие металлурги/химия; водоканалы — нет (у них
    воздуходувки), пищевка и прочие — только винтовые. «Большие» = выручка от 2 млрд ₽ (порог владельца 11.11)."""
    try: выр = float(str((р or {}).get("Выручка, млн ₽") or "0").replace(" ", "").replace(",", "."))
    except ValueError: выр = 0
    крупн = re.search(r"(?i)золот", отр) or (re.search(r"(?i)хими|лкм|металл", отр) and выр >= 2000)
    return random.choice(КОМПР_ОТД_КРУПН if крупн else КОМПР_ОТД)
СЕРВИС = ["У нас свой сервисный центр и свои инженеры.", "Сервис и инженеры - свои.", "Обслуживание ведут наши инженеры, сервисный центр свой."]
# владелец 11.11: исходим из того, что станция у них уже есть — спрашиваем про модернизацию/проект новой (b2b, не «покупку»), не про «переход»
ВОПРОС = ["Скажите, в планах на ближайшие 4 месяца есть модернизация {stanc_r}, проект новой или обновление компрессорной?",
          "Подскажите, планируете ли в ближайшие месяцы модернизацию {stanc_r} или проектирование новой?",
          "Есть ли в планах на ближайшие месяцы модернизация или проектирование новой {stanc_r}, обновление компрессоров?"]
ПЕРЕСЛАТЬ = ["Если этим занимается главный инженер или технолог, буду благодарен, если перешлёте ему письмо.",
             "Если вопрос не по вашей части, перешлите, пожалуйста, письмо главному инженеру или технологу."]
ЗАК = ["РУСАЛ", "РЖД", "«Северсталь»", "«Алроса»"]
ЗАК_ТВ = {"РУСАЛ": "РУСАЛом", "РЖД": "РЖД", "«Северсталь»": "«Северсталью»", "«Алроса»": "«Алросой»"}
ЗАК_ФР = ["Среди заказчиков {z}.", "Работали с {zt}.", "Среди наших заказчиков - {z}."]
def заказчики():
    з = random.sample(ЗАК, 3)
    return random.choice(ЗАК_ФР).format(z=", ".join(з[:-1]) + " и " + з[-1], zt=", ".join(ЗАК_ТВ[x] for x in з[:-1]) + " и " + ЗАК_ТВ[з[-1]])
def станция(отр, газ):
    """Фраза охвата с поправками по физике (сессия ЦА 11.11)."""
    if газ == "N2" and re.search(r"(?i)лазерн", отр):
        return "Под резку как раз проектируем и поставляем азотные станции с дожимом, в том числе модульные, сразу с компрессором и осушкой воздуха."
    if газ == "N2" and re.search(r"(?i)фарма", отр):
        return "Под такие процессы поставляем азотные станции под ключ с комплектом документов для GMP, в том числе модульные, в комплекте с компрессором и подготовкой воздуха."
    if газ == "N2" and re.search(r"(?i)пиво|вино|напит", отр):
        return "Для этого как раз проектируем и поставляем азотные станции высокой чистоты для контакта с продуктом, в том числе модульные, сразу с компрессором и осушкой воздуха."
    return random.choice(ОХВАТ[газ])
def годна(т, мин=8):
    т = (т or "").strip()
    if len(т.split()) < мин or len(т.split()) > 30: return "длина"
    if re.search(r"\d", т): return "цифры"
    if re.search(r"—|\bмы\b|\bнаш", т, re.I): return "мы/тире"
    if re.match(r"(?i)на производстве\b", т): return "общее начало"
    if re.search(r"(?i)вакуум", т): return "вакуум"
    if re.search(r"(?i)\b(дв(а|е|ух|ое)|тр(и|ёх|ех|ое)|четыр\w*|пят(и|ь)|шест(и|ь)|десят\w*|сотн\w*|тысяч\w*|полтор\w*)\b", т): return "число словами"
    return ""

# ---- отсев кодом по компании (то, что модель путала; владелец 11.11) ----
ОБЯЗ = [(r"(?i)фруктохран|ргс", r"(?i)фрукт|яблок|груш|сад|плод|ягод"),
        (r"(?i)сухое молоко", r"(?i)сух\w* молок|сухих? смес|молочн\w* смес|казеин|детск\w* (питан|смес)"),
        (r"(?i)озонирован", r"(?i)вод|озон"),
        (r"(?i)аэрозол", r"(?i)аэрозол|спрей|баллон|пропеллент|airless|дезодорант|лак для волос|пена")]
def отсев_кодом(р, отр, с):
    """Причина отсева компании кодом или "". р — строка файла заливки, с — строка полной базы по ИНН."""
    тут = " ".join([р.get("Продукция") or "", с.get("Продукция") or "", с.get("Оборудование, линии") or "", р.get("Компания") or ""])
    к = КОНК_РЕ.search(" ".join([р.get("Продукция") or "", с.get("Продукция") or "", с.get("Газы (паспорт)") or ""]))
    if к: return "конкурент (код: «%s»)" % к.group(0)
    for о, кл in ОБЯЗ:
        if re.search(о, отр) and not re.search(кл, тут): return "нет признаков отрасли"
    if re.search(r"(?i)золот", отр) and (re.search(r"(?i)россыпн", тут) or not re.search(r"(?i)руд|фабрик|зиф|цианир|обогат|кучн|выщелач|cil|cip", тут)):
        return "золото без ЗИФ/цианирования"
    if re.search(r"(?i)кофе", отр) and re.search(r"(?i)вендинг|автомат\w*\s+(unicum|necta|saeco|jettino)|парк оборудования|кофемашин|кофейн", тут):
        return "вендинг/кофемашины"
    if not (р.get("Продукция") or "").strip(): return "нет продукции"
    return ""
def фраза(f, газ):
    """Нормализация + проверка фразы модели. -> (фраза, беда)."""
    f = re.sub(r"\s*—\s*", " - ", (f or "").strip())
    if f and not re.search(r"[.!?]$", f): f += "."
    беда = годна(f)
    if not беда and газ == "O2" and re.search(r"(?i)резк|режут|резать|заправ", f): беда = "O2: резка/заправка"
    return f, беда
def строка_для_модели(i, отр, р, с):
    return "%d) отрасль: %s; продукция: %s; оборудование (сайт): %s; признаки газа на сайте: %s; газы (сайт): %s; техпроцесс отрасли: %s" % (
        i, отр, (р.get("Продукция") or "")[:300], (с.get("Оборудование, линии") or "")[:200] or "нет данных", с.get("Признаки газа на сайте") or "нет",
        с.get("Газы (паспорт)") or "нет", (р.get("Техпроцесс (где нужен газ)") or "")[:400])
def задание(газ, строки):
    return ЗАДАНИЕ.replace("{gaz}", "азот" if газ == "N2" else "кислород").replace("{firmy}", "\n".join(строки)).replace("{{", "{").replace("}}", "}")
def письмо(имя, менеджер, должность, f, отр, газ, р):
    """-> (тема, тело) по канону КЦ «по имени»."""
    тех = bool(имя and ТЕХ.search(должность or ""))
    тело = "\n\n".join([
        ((имя + ", добрый день!") if имя else "Добрый день!") + " Меня зовут " + менеджер + ", я из Компрессор Центра. " + random.choice(ПОВОД),
        f + " " + станция(отр, газ),
        компр(отр, р) + " " + заказчики() + " " + random.choice(СЕРВИС),
        random.choice(ВОПРОС).format(stanc_r=("азотной станции" if газ == "N2" else "кислородной станции")) + ("" if тех else " " + random.choice(ПЕРЕСЛАТЬ))])
    тема = random.choice(["Вопрос по %s на следующий год" % ("азоту" if газ == "N2" else "кислороду"),
                          "%s станция: планы на следующий год" % ("Азотная" if газ == "N2" else "Кислородная"),
                          "Вопрос по %s на производстве" % ("азоту" if газ == "N2" else "кислороду")])
    return тема, тело
